import{_ as a,o as r,c as t,af as i}from"./chunks/framework.EW8jFUkX.js";const u=JSON.parse('{"title":"Public Projects & Achievements","description":"","frontmatter":{},"headers":[],"relativePath":"projects.md","filePath":"projects.md"}'),o={name:"projects.md"};function n(s,e,l,c,h,d){return r(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="public-projects-achievements" tabindex="-1">Public Projects &amp; Achievements <a class="header-anchor" href="#public-projects-achievements" aria-label="Permalink to &quot;Public Projects &amp; Achievements&quot;">​</a></h1><h2 id="gpu-rsfk-gpu-random-sample-forest-knn" tabindex="-1">GPU-RSFK (GPU Random Sample Forest KNN) <a class="header-anchor" href="#gpu-rsfk-gpu-random-sample-forest-knn" aria-label="Permalink to &quot;GPU-RSFK (GPU Random Sample Forest KNN)&quot;">​</a></h2><p>GPU-accelerated (CUDA) approximate k-nearest-neighbor graph construction, exposing a Python API for large-scale workloads.</p><ul><li>What it does: builds an approximate K-NN Graph (K-NNG) using a Random Sample Forest KNN (RSFK) strategy with optional neighbor-exploration refinement.</li><li>Why it’s useful: reduces the cost of naive $O(n^2)$ neighborhood construction and targets million-scale point clouds.</li><li>Tech: CUDA + C/C++ core, Python bindings; Docker/Docker Compose support for reproducible builds.</li><li>Links: repo <a href="https://github.com/BrunoMeyer/gpu-rsfk" target="_blank" rel="noreferrer">github.com/BrunoMeyer/gpu-rsfk</a> (see also <code>DOCKER.md</code> and <code>examples/</code> in the repo)</li></ul><h2 id="mentored-testbed" tabindex="-1">MENTORED Testbed <a class="header-anchor" href="#mentored-testbed" aria-label="Permalink to &quot;MENTORED Testbed&quot;">​</a></h2><p>Cybersecurity experimentation testbed focused on repeatable “from modeling to experimentation” workflows (including DDoS and zero-day research contexts) under the MENTORED project.</p><ul><li>What it does: helps researchers define and automate experiment network topologies (YAML-driven), run experiments with pre-configured Docker images, and follow a guided workflow.</li><li>Context: cooperative academic/RNP initiative (Projeto Temático FAPESP/MCTIC 2018/23098-0).</li><li>Tech: a mix of TypeScript + Python + web assets; container-first approach.</li><li>Links: repo <a href="https://github.com/mentoredtestbed/MENTORED-Testbed" target="_blank" rel="noreferrer">github.com/mentoredtestbed/MENTORED-Testbed</a> (project site: <a href="https://mentored.dcc.ufmg.br/" target="_blank" rel="noreferrer">mentored.dcc.ufmg.br</a>)</li></ul><h2 id="microbiome-network-analysis-machine-learning" tabindex="-1">Microbiome Network Analysis (Machine Learning) <a class="header-anchor" href="#microbiome-network-analysis-machine-learning" aria-label="Permalink to &quot;Microbiome Network Analysis (Machine Learning)&quot;">​</a></h2><p>Pipeline + visualization artifacts for microbial community network analysis, developed in the context of an academic publication on anaerobic reactors.</p><ul><li>What it does: processes microbiome/taxon data, computes scores (including Random Forest–based feature importance), and produces interactive HTML pages.</li><li>Outputs: dashboards such as “Scores”, “Taxon importance chart”, and a correlation network/graph view.</li><li>Tech: Python + HTML + shell scripts; includes a Dockerfile for execution.</li><li>Links: repo <a href="https://github.com/BrunoMeyer/Microbiome-Network-with-Machine-Learning" target="_blank" rel="noreferrer">github.com/BrunoMeyer/Microbiome-Network-with-Machine-Learning</a></li></ul><h2 id="ssmt-ids" tabindex="-1">SSMT-IDS <a class="header-anchor" href="#ssmt-ids" aria-label="Permalink to &quot;SSMT-IDS&quot;">​</a></h2><p>Intrusion detection work applying deep learning techniques.</p><ul><li>Status: the provided GitHub link currently returns 404, so I couldn’t pull README details automatically.</li><li>Links: <a href="https://github.com/BrunoMeyer/ssmt-ids/" target="_blank" rel="noreferrer">github.com/BrunoMeyer/ssmt-ids</a></li></ul><h2 id="jmsa-2-java-mass-spectrometry-analyzer" tabindex="-1">JMSA 2 (Java Mass Spectrometry Analyzer) <a class="header-anchor" href="#jmsa-2-java-mass-spectrometry-analyzer" aria-label="Permalink to &quot;JMSA 2 (Java Mass Spectrometry Analyzer)&quot;">​</a></h2><p>Desktop Java application for analyzing MALDI-TOF mass spectrometry data for microorganism identification.</p><ul><li>Key features: spectra management/annotation, hierarchical clustering + Newick export, similarity search (Needleman–Wunsch based), “super spectra” generation, similarity matrix, and spectra visualization.</li><li>How to get it: releases and docs are linked from the repo (release line includes v2.1.3).</li><li>Tech: Java (desktop GUI), supporting libraries for charts/clustering/config.</li><li>Links: repo <a href="https://github.com/BrunoMeyer/jmsa" target="_blank" rel="noreferrer">github.com/BrunoMeyer/jmsa</a> (wiki: <a href="https://github.com/BrunoMeyer/jmsa/wiki" target="_blank" rel="noreferrer">github.com/BrunoMeyer/jmsa/wiki</a>)</li></ul><h2 id="him-healthcare-intelligent-map" tabindex="-1">HIM (Healthcare Intelligent Map) <a class="header-anchor" href="#him-healthcare-intelligent-map" aria-label="Permalink to &quot;HIM (Healthcare Intelligent Map)&quot;">​</a></h2><p>Front-end data visualization tool for healthcare reports: users upload a spreadsheet and the processing happens locally in the browser.</p><ul><li>What it does: visualizes and searches patient/report data on Google Maps (markers + polygons), including filters (diseases, programs, active/inactive).</li><li>Architecture notes: uses Firebase + Google Maps APIs; includes local caching to reduce repeated geocoding/lookups.</li><li>Tech: JavaScript + HTML/CSS; no centralized backend required.</li><li>Links: repo <a href="https://github.com/BrunoMeyer/healthcare_inteligent_map" target="_blank" rel="noreferrer">github.com/BrunoMeyer/healthcare_inteligent_map</a></li></ul><h1 id="highlights" tabindex="-1">Highlights <a class="header-anchor" href="#highlights" aria-label="Permalink to &quot;Highlights&quot;">​</a></h1><ul><li>Led a development team to implement <strong>MENTORED Testbed</strong>: a cybersecurity testbed and web system with a cloud-provider-like workflow (provisioning, access, monitoring) for multi-cluster Kubernetes environments. Intended as a self-hosted alternative to cloud providers.</li><li>Obtained research funding to present articles at relevant international conferences.</li><li>Invited to serve on master’s thesis committees, teach courses at academic/technical events, and give academic lectures.</li><li>Ongoing personal project: enabling Docker and Kubernetes on Android by developing a new container runtime (CRI) and forking Minikube/Kubernetes to modify the Kubelet module.</li></ul>',21)])])}const m=a(o,[["render",n]]);export{u as __pageData,m as default};
